// STYLES
// ============================================================================

const TIRE_SIZE = 64;
const TIRE_HIT_SIZE = 84;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: "#FFFFFF",
    borderRadius: 20,
    overflow: "hidden",
    alignItems: "center",
    justifyContent: "center",
  },
  carFrame: {
    width: 160,
    height: 240,
    position: "relative",
  },
  carImage: {
    width: 160,
    height: 240,
    position: "absolute",
    top: 0,
    left: 0,
  },
  tireWrap: {
    position: "absolute",
    width: TIRE_HIT_SIZE,
    height: TIRE_HIT_SIZE,
    marginLeft: -TIRE_HIT_SIZE / 2,
    marginTop: -TIRE_HIT_SIZE / 2,
    alignItems: "center",
    justifyContent: "center",
  },
  tireHitArea: {
    width: TIRE_HIT_SIZE,
    height: TIRE_HIT_SIZE,
    alignItems: "center",
    justifyContent: "center",
  },
});
